/** Traduit un message d'erreur du serveur ; renvoie le message d'origine s'il est inconnu ou si lang vaut "fr". */
export function translateServerMessage(message, lang) {
  if (typeof message !== "string" || (lang !== "es" && lang !== "en")) return message;
  const entry = SERVER_MESSAGES[message];
  if (entry) return lang === "es" ? entry[0] : entry[1];
  // Messages bilingues « français / español » : garder la partie dans la bonne langue si elle existe.
  if (message.includes(" / ")) {
    const parts = message.split(" / ");
    if (lang === "es" && parts[1]) return parts[1];
  }
  return message;
}
